    [6, 0, 0, 0, 0, 0, 0, 0, 6, 6, 6, 0, 0, 6, 6, 0, 0, 0, 0, 0, 0, 6, 6, 0, 0, 0, 0],
]

def apply_rule2d(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    component_size = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and not visited[r][c]:
                component = []
                queue = [(r,c)]
                visited[r][c] = True
                while queue:
                    cr, cc = queue.pop(0)
                    component.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] != 0 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                size = len(component)
                for (cr, cc) in component:
                    component_size[cr][cc] = size

    result = [[0]*cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == 0:
                result[r][c] = 0
            elif component_size[r][c] == 1 and val in [2, 5, 6]:
                result[r][c] = 6  # stay same
            else:
                result[r][c] = 8
    return result

result = apply_rule2d(input_test)

# Output
print("Output grid:")
for row in result:
    print(row)

print("\nAs nested lists:")
print(result)
